    "articles": {
      "backLink": "← Back to Insights",
      "article1date": "Executive Perspective",
      "article1title": "From Engineering to Global Data Infrastructure",
      "article1p1": "My career began at the Nikolaev Shipbuilding Plant in Ukraine, developing satellite transceiver systems for transmitting classified information to military ships. I was recognized as an electronics engineer of the highest level — the 6th category at a plant of 93,000 employees.",
      "article1p2": "From 1989 to 1994, I founded and led Astra Corp, a manufacturer of digital transceiver satellite systems. From 1994 to 1996, as CEO of Elitan United Inc., I led IT strategy and infrastructure during a period of rapid expansion.",
      "article1p3": "In 1996, I founded 9 Net Avenue Inc., a hosting and internet infrastructure company. In 2000 it was acquired by Concentric Networks (NASDAQ: CNTX) and subsequently became part of XO Communications (NASDAQ: XOXO).",
      "article1p4": "From 2001 to 2019, I directed technology strategy for government, defense, and state-owned enterprise programs — leading large-scale initiatives in big data, secure infrastructure, and high-throughput data centers across the United States and Europe.",
      "article2date": "Digital Health",
      "article2title": "Precision Medicine and the Convergence of Science and Technology",
      "article2p1": "Life sciences advance when rigorous technology is applied to evidence, interpretation, and clinical utility.",
      "article2p2": "Under my leadership, successful genetic testing projects were initiated in Ukraine, Russia, and the Baltic countries. In collaboration with Harvard Medical School and Stanford Biomath, I played a crucial role in developing easily understandable genetic reports for both doctors and patients.",
      "article2p3": "With Digital Invest Inc., founded in 2021, we work in bio-mathematical medicine — applying science, DNA technologies, AI, and ML to clinical intelligence. Healthcare Tech Outlook featured the company in 2023.",
      "article2p4": "Digital Invest advances bio-mathematical medicine through projects including Human Digital Model and BioMath Life. In 2026, Michael Kofman founded AGRON Inc. to lead the Aerial-Ground Robotics Operations Network — UAV capability development, geospatial systems, and maritime intelligence at agron1.com."
    },
