    "board": {
      "eyebrow": "Asesoría",
      "title": "Asesoría",
      "body": "Abierto a conversaciones de asesoría estratégica con organizaciones de tecnología, salud e infraestructura — basándome en experiencia operativa directa en creación de empresas, estrategia tecnológica y ejecución en etapas de crecimiento.",
      "contactLink": "Para consultas de asesoría",
      "lead": "Board & Advisory"
    },
    "thesis": {
      "eyebrow": "Tesis de liderazgo",
      "title": "Construir a largo plazo. Decidir en el presente.",
      "lead": "La tecnología cambia rápido; las obligaciones del liderazgo, no. Las empresas duraderas unen ambición con disciplina, evidencia y responsabilidad.",
      "believeEyebrow": "En qué creo",
      "believeTitle": "Siete principios para organizaciones duraderas",
      "b1title": "La estrategia debe producir decisiones",
      "b1text": "Una estrategia no es un catálogo de aspiraciones. Define dónde competir, qué capacidades construir, qué no perseguir y cómo se medirá el éxito.",
      "b2title": "La tecnología es un asunto de gobernanza",
      "b2text": "Los consejos deben entender cómo la tecnología crea valor, concentra riesgo y cambia la responsabilidad. Delegar cada pregunta técnica es en sí una decisión.",
      "b3title": "La evidencia debe superar al entusiasmo",
      "b3text": "La convicción importa, pero mercados, sistemas y ciencia deben probarse. Los líderes crean mecanismos que exponen supuestos antes que clientes o reguladores.",
      "b4title": "La arquitectura moldea la empresa",
      "b4text": "La arquitectura técnica determina velocidad, resiliencia, seguridad y opciones futuras. Los atajos se convierten en restricciones institucionales mucho después de que desaparece su contexto original.",
      "b5title": "La confianza es infraestructura operativa",
      "b5text": "La confianza se construye con compromisos claros, ejecución fiable, prácticas responsables de datos y comunicación directa cuando cambian las condiciones.",
      "b6title": "El capital debe seguir a la capacidad",
      "b6text": "La inversión en crecimiento debe reforzar capacidades diferenciadas y demanda medible, no sustituir el gasto por comprensión del producto-mercado.",
      "b7title": "Los líderes diseñan a sus sucesores",
      "b7text": "Los líderes más sólidos construyen sistemas, talento y calidad de decisión que perduran más allá de su propia participación.",
      "rejectEyebrow": "Lo que rechazo",
      "rejectTitle": "Tres ilusiones costosas",
      "r1title": "Teatro de innovación",
      "r1text": "Anuncios, pilotos y lenguaje de moda no equivalen a capacidad. La innovación debe mejorar un resultado que importa.",
      "r2title": "Crecimiento sin gobernanza",
      "r2text": "La escala magnifica debilidades no resueltas. Controles, cultura y responsabilidad deben madurar antes de que la complejidad haga costosa la corrección.",
      "r3title": "Falsa certeza",
      "r3text": "La confianza ejecutiva no debe borrar la incertidumbre. Las decisiones sólidas hacen visibles los supuestos y preservan opciones cuando cambian los hechos.",
      "horizonEyebrow": "El horizonte",
      "horizonTitle": "La próxima ventaja es la integración responsable",
      "horizonText": "La oportunidad definitoria no es una sola tecnología. Es la integración disciplinada de IA, sistemas avanzados de datos, biología y automatización en instituciones en las que la gente puede confiar."
    },
