      "bioMedium": "Michael Kofman ist CEO von Digital Invest Inc. und Mitglied des Board of Directors. Als Technologie-Visionär ist er für seinen dynamischen Ansatz bekannt, die sich ständig wandelnden Anforderungen des heutigen komplexen Marktes zu verstehen. Als Unternehmer, Board-Mitglied und Berater öffentlicher und privater Unternehmen hat er in den USA und Europa mehrere Unternehmen erfolgreich aufgebaut. Seine Expertise umfasst Executive Leadership, strategische Analyse neuer Technologien und Märkte, Informationssicherheit und Datenschutz, Forschung, Wissenschaft und Entwicklung, Administration und Investment.",
      "bioLongLabel": "500 Wörter",
      "bioLong": "Michael Kofman ist CEO von Digital Invest Inc. und Mitglied des Boards. Er gründete 9 Net Avenue Inc., 2000 von Concentric Networks übernommen, und leitet Digital Invest in biomathematischer Medizin und genomischer Intelligenz. Er gründete AGRON Inc. 2026 für autonome Luft-Boden-Operationen und geospatiale Systeme. Autor technischer Arbeiten zu Satelliten- und optischen Systemen; Patent für digitales Satelliten-HDTV, übernommen von Sony. Ausbildung: Doctor of Technical Sciences, Ph.D. in Information Technology.",
      "photosEyebrow": "Fotografie",
      "photosTitle": "Freigegebene Bilder",
      "photosLead": "Hochauflösende Porträts sind auf Anfrage unter mkofman@mkofman.com erhältlich.",
      "contactEyebrow": "Pressekontakt",
      "contactTitle": "Medienanfragen",
      "contactLead": "Für Interviews, Vortragseinladungen und Presseanfragen.",
