    "articles": {
      "backLink": "← Zurück zu Insights",
      "article1date": "Führungsperspektive",
      "article1title": "Von der Ingenieurtechnik zur globalen Dateninfrastruktur",
      "article1p1": "Meine Karriere begann im Schiffbauwerk Nikolaev in der Ukraine, wo ich Satelliten-Transceiversysteme zur Übertragung klassifizierter Informationen an Kriegsschiffe entwickelte. Ich wurde als Elektronikingenieur höchster Stufe ausgezeichnet, der 6. Kategorie in einem Werk mit 93.000 Mitarbeitenden.",
      "article1p2": "Von 1989 bis 1994 gründete und leitete ich Astra Corp, einen der größten europäischen Hersteller digitaler Satelliten-Transceiversysteme. Von 1994 bis 1996 half ich als CEO von Elitan United Inc., das Unternehmen von neun auf über 4.000 Mitarbeitende weltweit zu skalieren.",
      "article1p3": "1996 gründete ich 9 Net Avenue Inc., ein Hosting- und Internet-Infrastrukturunternehmen. 2000 wurde es von Concentric Networks (NASDAQ: CNTX) übernommen und später Teil von XO Communications (NASDAQ: XOXO).",
      "article1p4": "Von 2001 bis 2019 verantwortete ich die Technologiestrategie für Regierungs-, Verteidigungs- und Staatsunternehmensprogramme und leitete groß angelegte Initiativen in Big Data, sicherer Infrastruktur und Hochdurchsatz-Rechenzentren in den USA und Europa.",
      "article2date": "Digitale Gesundheit",
      "article2title": "Präzisionsmedizin und die Konvergenz von Wissenschaft und Technologie",
      "article2p1": "Ich bin fest davon überzeugt, dass die Kombination von Life Sciences mit den neuesten technologischen Fortschritten enormes Potenzial bietet. Bei Biotechnology Group Inc. (2008-2014) konzentrierten wir uns auf DNA-Tests und -Analysen, Prozessautomatisierung zur Erstellung genetischer Profile und umfassende humangenetische Forschung.",
      "article2p2": "Unter meiner Leitung wurden erfolgreiche genetische Testprojekte in der Ukraine, in Russland und in den baltischen Staaten initiiert. In Zusammenarbeit mit Harvard Medical School und Stanford Biomath spielte ich eine entscheidende Rolle bei der Entwicklung leicht verständlicher genetischer Berichte für Ärzte und Patienten.",
      "article2p3": "Mit Digital Invest Inc., gegründet 2021, arbeiten wir in biomathematischer Medizin — Wissenschaft, DNA-Technologien, KI und ML in klinischer Intelligenz. Healthcare Tech Outlook (2023).",
      "article2p4": "Digital Invest umfasst vielfältige innovative Projekte, darunter Human Digital Model, BioMath Life und Aero-Ground Robotics Operations Network, die jeweils die Integration von Data Science und Life Sciences vorantreiben."
    },
