    "board": {
      "eyebrow": "Beratung",
      "title": "Beratung",
      "body": "Offen für strategische Advisory-Gespräche mit Technologie-, Gesundheits- und Infrastrukturorganisationen — auf Basis direkter Operating-Erfahrung in Unternehmensaufbau, Technologiestrategie und Wachstumsphasen.",
      "contactLink": "Für Advisory-Anfragen",
      "lead": "Board & Advisory"
    },
    "thesis": {
      "eyebrow": "Führungsthese",
      "title": "Für die Langzeit bauen. In der Gegenwart entscheiden.",
      "lead": "Technologie ändert sich schnell; die Pflichten der Führung nicht. Beständige Unternehmen verbinden Ambition mit Disziplin, Evidenz und Accountability.",
      "believeEyebrow": "Woran ich glaube",
      "believeTitle": "Sieben Prinzipien für beständige Organisationen",
      "b1title": "Strategie muss Entscheidungen erzeugen",
      "b1text": "Strategie ist kein Katalog von Aspirationen. Sie definiert, wo zu konkurrieren ist, welche Fähigkeiten aufzubauen sind, was nicht verfolgt werden soll und wie Erfolg gemessen wird.",
      "b2title": "Technologie ist eine Governance-Frage",
      "b2text": "Boards müssen verstehen, wie Technologie Wert schafft, Risiko konzentriert und Accountability verändert. Jede technische Frage zu delegieren ist selbst eine Entscheidung.",
      "b3title": "Evidenz soll Enthusiasmus übertrumpfen",
      "b3text": "Überzeugung zählt, aber Märkte, Systeme und Wissenschaft müssen getestet werden. Führungskräfte schaffen Mechanismen, die Annahmen sichtbar machen, bevor Kunden oder Regulatoren es tun.",
      "b4title": "Architektur formt das Unternehmen",
      "b4text": "Technische Architektur bestimmt Geschwindigkeit, Resilienz, Sicherheit und zukünftige Optionen. Abkürzungen werden zu institutionellen Zwängen lange nach ihrem ursprünglichen Kontext.",
      "b5title": "Vertrauen ist Operating-Infrastruktur",
      "b5text": "Vertrauen entsteht durch klare Zusagen, verlässliche Ausführung, verantwortungsvolle Datenpraxis und direkte Kommunikation, wenn sich Bedingungen ändern.",
      "b6title": "Kapital muss der Fähigkeit folgen",
      "b6text": "Wachstumsinvestitionen sollten differenzierte Fähigkeiten und messbare Nachfrage stärken, nicht Ausgaben für Product-Market-Understanding ersetzen.",
      "b7title": "Führungskräfte gestalten ihre Nachfolger",
      "b7text": "Die stärksten Führungskräfte bauen Systeme, Talent und Entscheidungsqualität, die über ihre eigene Beteiligung hinaus Bestand haben.",
      "rejectEyebrow": "Was ich ablehne",
      "rejectTitle": "Drei teure Illusionen",
      "r1title": "Innovations-Theater",
      "r1text": "Ankündigungen, Piloten und modische Sprache sind keine Fähigkeit. Innovation muss ein Ergebnis verbessern, das zählt.",
      "r2title": "Wachstum ohne Governance",
      "r2text": "Skalierung vergrößert ungelöste Schwächen. Controls, Kultur und Accountability sollten reifen, bevor Komplexität Korrektur kostspielig macht.",
      "r3title": "Falsche Gewissheit",
      "r3text": "Executive Confidence soll Unsicherheit nicht tilgen. Starke Entscheidungen machen Annahmen sichtbar und bewahren Optionen, wenn Fakten sich ändern.",
      "horizonEyebrow": "Der Horizont",
      "horizonTitle": "Der nächste Vorteil ist verantwortungsvolle Integration",
      "horizonText": "Die entscheidende Chance ist nicht eine einzelne Technologie. Es ist die disziplinierte Integration von KI, fortgeschrittenen Datensystemen, Biologie und Automation in Institutionen, denen Menschen vertrauen können."
    },
