      "lead": "Biographies officielles, visuels et coordonnées pour la presse, les conférences et les demandes de conseil d'administration.",
      "bioEyebrow": "Biographies officielles",
      "bioTitle": "Biographies officielles",
      "bioShortLabel": "50 mots",
      "bioShort": "Michael Kofman est CEO de Digital Invest Inc., administrateur, conseiller et fondateur d'entreprises technologiques et de santé numérique aux États-Unis et en Europe.",
      "bioMediumLabel": "150 mots",
      "bioMedium": "Michael Kofman est CEO de Digital Invest Inc. et siège à son Board of Directors. Visionnaire technologique, il est reconnu pour son approche dynamique des besoins en constante évolution des marchés complexes actuels. Entrepreneur, administrateur et conseiller auprès d'entreprises publiques et privées, il a fondé avec succès plusieurs sociétés aux États-Unis et en Europe. Son expertise couvre la direction exécutive, l'analyse stratégique des technologies et marchés émergents, la sécurité et la confidentialité de l'information, la recherche, la science et le développement, l'administration et l'investissement.",
      "bioLongLabel": "500 mots",
      "bioLong": "Michael Kofman est CEO de Digital Invest Inc. et membre de son conseil. Il a fondé 9 Net Avenue Inc., acquise par Concentric Networks en 2000, et dirige Digital Invest en médecine biomathématique et intelligence génomique. Il a fondé AGRON Inc. en 2026 pour opérations autonomes aéro-terrestres et systèmes géospatiaux. Auteur de travaux techniques sur systèmes satellitaires et optiques ; brevet HDTV satellitaire numérique acquis par Sony. Formation : Doctor of Technical Sciences, Ph.D. in Information Technology.",
