    "board": {
      "eyebrow": "Conseil",
      "title": "Conseil",
      "body": "Ouvert aux conversations de conseil stratégique avec des organisations technologiques, de santé et d'infrastructure — s'appuyant sur une expérience opérationnelle directe en création d'entreprises, stratégie technologique et exécution en phase de croissance.",
      "contactLink": "Pour les demandes de conseil",
      "lead": "Board & Advisory"
    },
    "thesis": {
      "eyebrow": "Thèse de leadership",
      "title": "Construire pour le long terme. Décider dans le présent.",
      "lead": "La technologie change vite ; les obligations du leadership, non. Les entreprises durables unissent ambition, discipline, preuves et responsabilité.",
      "believeEyebrow": "Ce en quoi je crois",
      "believeTitle": "Sept principes pour des organisations durables",
      "b1title": "La stratégie doit produire des choix",
      "b1text": "Une stratégie n'est pas un catalogue d'aspirations. Elle définit où concurrencer, quelles capacités construire, quoi ne pas poursuivre et comment le succès sera mesuré.",
      "b2title": "La technologie est un enjeu de gouvernance",
      "b2text": "Les conseils doivent comprendre comment la technologie crée de la valeur, concentre le risque et change la responsabilité. Déléguer chaque question technique est déjà une décision.",
      "b3title": "Les preuves doivent primer sur l'enthousiasme",
      "b3text": "La conviction compte, mais marchés, systèmes et science doivent être testés. Les dirigeants créent des mécanismes qui exposent les hypothèses avant clients ou régulateurs.",
      "b4title": "L'architecture façonne l'entreprise",
      "b4text": "L'architecture technique détermine vitesse, résilience, sécurité et options futures. Les raccourcis deviennent des contraintes institutionnelles longtemps après leur contexte d'origine.",
      "b5title": "La confiance est une infrastructure opérationnelle",
      "b5text": "La confiance se construit par des engagements clairs, une exécution fiable, des pratiques responsables des données et une communication directe quand les conditions changent.",
      "b6title": "Le capital doit suivre la capacité",
      "b6text": "L'investissement de croissance doit renforcer des capacités différenciées et une demande mesurable, pas substituer les dépenses à la compréhension produit-marché.",
      "b7title": "Les dirigeants conçoivent leurs successeurs",
      "b7text": "Les dirigeants les plus solides construisent des systèmes, des talents et une qualité de décision qui perdurent au-delà de leur propre participation.",
      "rejectEyebrow": "Ce que je rejette",
      "rejectTitle": "Trois illusions coûteuses",
      "r1title": "Théâtre de l'innovation",
      "r1text": "Annonces, pilotes et langage à la mode ne font pas une capacité. L'innovation doit améliorer un résultat qui compte.",
      "r2title": "Croissance sans gouvernance",
      "r2text": "L'échelle amplifie les faiblesses non résolues. Contrôles, culture et responsabilité doivent mûrir avant que la complexité ne rende la correction coûteuse.",
      "r3title": "Fausse certitude",
      "r3text": "La confiance exécutive ne doit pas effacer l'incertitude. Les bonnes décisions rendent les hypothèses visibles et préservent les options quand les faits changent.",
      "horizonEyebrow": "L'horizon",
      "horizonTitle": "Le prochain avantage est l'intégration responsable",
      "horizonText": "L'opportunité décisive n'est pas une seule technologie. C'est l'intégration disciplinée de l'IA, des systèmes de données avancés, de la biologie et de l'automatisation dans des institutions auxquelles on peut faire confiance."
    },
