    "thesis": {
      "eyebrow": "Тезис лидерства",
      "title": "Строить надолго. Решать — сейчас.",
      "lead": "Технологии меняются быстро; обязательства лидерства — нет. Устойчивые компании соединяют амбиции с дисциплиной, доказательствами и подотчётностью.",
      "believeEyebrow": "Вo что я верю",
      "believeTitle": "Семь принципов для устойчивых организаций",
      "b1title": "Стратегия должна порождать выбор",
      "b1text": "Стратегия — не каталог амбиций. Она определяет, где конкурировать, какие способности строить, чего не pursue и как измерять успех.",
      "b2title": "Технология — вопрос управления",
      "b2text": "Советы директоров должны понимать, как технология создаёт ценность, концентрирует риск и меняет подотчётность. Делегирование каждого технического вопроса — само по себе решение.",
      "b3title": "Доказательства важнее энтузиазма",
      "b3text": "Убеждённость важна, но рынки, системы и науку нужно проверять. Лидеры создают механизмы, выявляющие допущения раньше клиентов или регуляторов.",
      "b4title": "Архитектура формирует компанию",
      "b4text": "Техническая архитектура определяет скорость, устойчивость, безопасность и будущие опции. Shortcut'ы становятся институциональными ограничениями long after исчезновения их контекста.",
      "b5title": "Доверие — операционная инфраструктура",
      "b5text": "Доверие строится через ясные обязательства, надёжное исполнение, ответственную работу с данными и прямую коммуникацию при изменении условий.",
      "b6title": "Капитал должен следовать за способностями",
      "b6text": "Инвестиции в рост должны усиливать дифференцированные способности и измеримый спрос, а не заменять траты пониманием product-market.",
      "b7title": "Лидеры проектируют своих преемников",
      "b7text": "Сильнейшие лидеры строят системы, таланты и качество решений, которые переживают их собственное участие.",
      "rejectEyebrow": "Что я отвергаю",
      "rejectTitle": "Три дорогих иллюзии",
      "r1title": "Театр инноваций",
      "r1text": "Анонсы, пилоты и модный язык не равны capability. Инновации должны улучшать результат, который имеет значение.",
      "r2title": "Рост без управления",
      "r2text": "Масштаб увеличивает нерешённые слабости. Controls, culture и accountability должны созреть, пока complexity не сделает correction costly.",
      "r3title": "Ложная определённость",
      "r3text": "Executive confidence не должна стирать uncertainty. Сильные решения делают assumptions visible и сохраняют options при изменении facts.",
      "horizonEyebrow": "Горизонт",
      "horizonTitle": "Следующее преимущество — ответственная интеграция",
      "horizonText": "Решающая возможность — не одна технология. Это дисциплинированная интеграция ИИ, продвинутых data systems, биологии и automation в institution, которым люди могут доверять."
    },
