    "deck": {
      "title": "Michael Kofman",
      "subtitle": "Технологический executive · Основатель · Советник",
      "thesis": "Технологии, бизнес и инвестиции в инфраструктуру, life sciences и автономные системы.",
      "contact": "Конфиденциальное обсуждение: связаться с Michael Kofman через mkofman.com"
    },
    "briefIpo": {
      "title": "Что меняет IPO",
      "desc": "Публичные рынки меняют не только capital structure; они меняют operating contract.",
      "p1": "IPO часто описывают как financing event. На практике это institutional transition. Forecasting, controls, disclosure, governance и executive communication должны стать repeatable до listing, а не improvised после.",
      "p2": "Readiness начинается с decision quality. Management нужны reliable metrics, clear ownership и operating cadence, способный объяснить performance и variance. Компания, не reconciling internal narrative, будет struggle с credible external one.",
      "p3": "Роль board тоже меняется. Directors должны balance growth и oversight, понимать material technology и market risks и ensure, что incentives support durable value, а не single quarter.",
      "p4": "Сильнейшие public companies сохраняют entrepreneurial speed, добавляя institutional discipline. Objective — не bureaucracy; это trustworthy execution на более высоком уровне accountability.",
      "eyebrow": "Исполнительный бриф"
    },
    "briefGenetic": {
      "title": "От генетических данных к клиническим решениям",
      "desc": "Ценность геномной информации зависит от интерпретации, доказательной базы и ответственной интеграции в клиническую практику.",
      "p1": "Генетических данных много; clinically useful meaning — редкость. Результат становится ценным только когда интерпретирован в контексте, связан с validated evidence и представлен в форме, поддерживающей реальное решение.",
      "p2": "Такой перевод требует collaboration между molecular biology, medicine, statistics, software engineering и patient communication. Слабость на любом уровне превращает техническую sophistication в clinical confusion.",
      "p3": "Privacy и consent — architectural requirements, а не legal footnotes. Системы должны ограничивать unnecessary exposure, делать data provenance visible и сохранять patient agency при движении информации между laboratories, platforms и care teams.",
      "p4": "Прецизионная медицина будет развиваться через измеренную интеграцию: лучшие доказательства, прозрачные модели, interoperable workflows и результаты, которые могут оценить клиницисты и пациенты. Доверие — часть продукта.",
      "eyebrow": "Исполнительный бриф"
    },
    "briefAi": {
      "title": "Стратегия ИИ за пределами пилота",
      "desc": "Корпоративный ИИ создаёт ценность, когда ownership, данные, workflow и governance созревают вместе.",
      "p1": "Многие AI-инициативы начинаются с убедительной демонстрации и останавливаются до production. Недостающим элементом редко бывает одна только модель. Устойчивая ценность требует определённого business outcome, ответственного владельца, надёжных данных и workflow, которым люди действительно пользуются.",
      "p2": "Лидерам следует различать automation, prediction и decision support. У каждого — разные требования к точности, explainability, human review и риску. Единый governance-шаблон не подходит для всех use cases.",
      "p3": "Измерение должно включать больше, чем техническую производительность. Adoption, cycle time, error rates, customer impact, security exposure и cost of supervision определяют, является ли AI-capability экономически и institutionally sound.",
      "p4": "Выигрышный подход — managed portfolio: масштабировать proven use cases, рано останавливать слабые и поддерживать explicit boundaries для high-consequence decisions. AI strategy — это ultimately operating strategy.",
      "eyebrow": "Исполнительный бриф"
    },
