      "cs3desc": "Заснована у 2026 році — екосистема AGRON для БПЛА, геопространствених систем і морської розвідки.",
      "heroName": "Michael Kofman",
      "heroRole": "Технологічний executive · Засновник · Радник",
      "introText": "Michael Kofman — технологічний executive і засновник компаній. Його робота охоплює супутникову інженерію, інтернет-інфраструктуру, публічні технологічні компанії та life sciences. Він заснував 9 Net Avenue Inc., придбану Concentric Networks у 2000 році. CEO Digital Invest Inc. у біоматематичній медицині та геномній аналітиці; засновник AGRON Inc. в автономних повітряно-наземних операціях і геопросторових системах. Бере участь у радах директорів і консультує в технологіях, охороні здоров'я та інфраструктурі.",
