    "articles": {
      "backLink": "← Назад до Insights",
      "article1date": "Виконавча перспектива",
      "article1title": "Від інженерії до глобальної інфраструктури даних",
      "article1p1": "Моя кар'єра почалася на Миколаївському суднобудівному заводі в Україні, де я розробляв супутникові трансиверні системи для передавання засекреченої інформації військовим кораблям. Мене визнали інженером-електронщиком найвищого рівня — 6-ї категорії на підприємстві з 93 000 працівників.",
      "article1p2": "У 1989-1994 роках я заснував і очолював Astra Corp, одного з найбільших у Європі виробників цифрових супутникових трансиверних систем. У 1994-1996 роках, як CEO Elitan United Inc., я допоміг масштабувати компанію з дев'яти до понад 4 000 працівників у світі.",
      "article1p3": "У 1996 році я заснував 9 Net Avenue Inc. — компанію хостингу та інтернет-інфраструктури. У 2000 році її придбала Concentric Networks (NASDAQ: CNTX), а згодом вона стала частиною XO Communications (NASDAQ: XOXO).",
      "article1p4": "У 2001-2019 роках я керував технологічною стратегією для державних, оборонних і квазідержавних програм, очолюючи масштабні ініціативи у сфері big data, захищеної інфраструктури та високопродуктивних дата-центрів у США та Європі.",
      "article2date": "Цифрове охорону здоров'я",
      "article2title": "Прецизійна медицина та конвергенція науки й технологій",
      "article2p1": "Я переконаний у потенціалі поєднання наук про життя з найновішими технологічними досягненнями. У Biotechnology Group Inc. (2008-2014) ми зосереджувалися на ДНК-тестуванні та аналізі, автоматизації процесів створення генетичних профілів і комплексних дослідженнях генетики людини.",
      "article2p2": "Під моїм керівництвом було започатковано успішні проєкти генетичного тестування в Україні, Росії та країнах Балтії. У співпраці з Harvard Medical School і Stanford Biomath я відіграв ключову роль у створенні зрозумілих генетичних звітів як для лікарів, так і для пацієнтів.",
      "article2p3": "З Digital Invest Inc., заснованою у 2021, працюємо в біоматематичній медицині — наука, ДНК-технології, ШІ та ML у кlinічній аналітиці. Healthcare Tech Outlook (2023).",
      "article2p4": "Digital Invest об'єднує інноваційні проєкти, зокрема Human Digital Model, BioMath Life та Aero-Ground Robotics Operations Network, кожен з яких посилює інтеграцію data science і наук про життя."
    },
