    "briefIpo": {
      "title": "Що змінює IPO",
      "desc": "Публічні ринки змінюють не лише capital structure; вони змінюють operating contract.",
      "p1": "IPO часто описують як financing event. На практиці це institutional transition. Forecasting, controls, disclosure, governance і executive communication мають стати repeatable до listing, а не improvised після.",
      "p2": "Readiness починається з decision quality. Management потрібні reliable metrics, clear ownership і operating cadence, здатний пояснити performance і variance. Компанія, що не reconciling internal narrative, буде struggle з credible external one.",
      "p3": "Роль board теж змінюється. Directors мають balance growth і oversight, розуміти material technology і market risks і ensure, що incentives support durable value, а не single quarter.",
      "p4": "Найсильніші public companies зберігають entrepreneurial speed, додаючи institutional discipline. Objective — не bureaucracy; це trustworthy execution на вищому рівні accountability.",
      "eyebrow": "Виконавчий бриф"
    },
    "briefGenetic": {
      "title": "Від генетичних даних до клінічних рішень",
      "desc": "Цінність геномної інформації залежить від інтерпретації, доказової бази та відповідальної інтеграції в клінічну практику.",
      "p1": "Генетичних даних багато; clinically useful meaning — рідкість. Результат стає цінним лише коли інтерпретований у контексті, пов'язаний із validated evidence і поданий у формі, що підтримує реальне рішення.",
      "p2": "Такий переклад потребує collaboration між molecular biology, medicine, statistics, software engineering і patient communication. Слабкість на будь-якому рівні перетворює technical sophistication на clinical confusion.",
      "p3": "Privacy і consent — architectural requirements, а не legal footnotes. Системи мають обмежувати unnecessary exposure, робити data provenance visible і зберігати patient agency під час руху інформації між laboratories, platforms і care teams.",
      "p4": "Прецизійна медицина розвиватиметься через вимірювану інтеграцію: кращі докази, прозорі моделі, interoperable workflows і результати, які можуть оцінити клініцисти та пацієнти. Довіра — частина продукту.",
      "eyebrow": "Виконавчий бриф"
    },
    "briefAi": {
      "title": "Стратегія ШІ за межами пілота",
      "desc": "Корпоративний ШІ створює цінність, коли ownership, дані, workflow і governance дозрівають разом.",
      "p1": "Багато AI-ініціатив починаються з переконливої демонстрації й зупиняються до production. Бракує рідко лише моделі. Стійка цінність потребує визначеного business outcome, відповідального власника, надійних даних і workflow, яким люди справді користуються.",
      "p2": "Лідерам варто розрізняти automation, prediction і decision support. Кожен має різні вимоги до точності, explainability, human review і ризику. Єдиний governance-шаблон не підходить для всіх use cases.",
      "p3": "Вимірювання має включати більше, ніж технічну продуктивність. Adoption, cycle time, error rates, customer impact, security exposure і cost of supervision визначають, чи є AI-capability економічно та institutionally sound.",
      "p4": "Переможний підхід — managed portfolio: масштабувати proven use cases, рано зупиняти слабкі та підтримувати explicit boundaries для high-consequence decisions. AI strategy — це ultimately operating strategy.",
      "eyebrow": "Виконавчий бриф"
    },
