      "bioEyebrow": "传记",
      "bioTitle": "官方简介",
      "bioShortLabel": "50 词",
      "bioShort": "Michael Kofman 是 Digital Invest Inc. 的 CEO，同时担任董事会成员、顾问，并在美国和欧洲创办多家科技与数字健康企业。",
      "bioMediumLabel": "150 词",
      "bioMedium": "Michael Kofman 是 Digital Invest Inc. 的 CEO，并担任其董事会成员。作为技术远见者，他以动态方式洞察当今复杂市场不断变化的需求。作为企业家、董事会成员以及公私营企业顾问，他已在美国和欧洲成功创办多家公司。其专长覆盖高管领导力、新兴技术与市场战略分析、信息安全与隐私、科研与开发、管理及投资。",
      "bioLongLabel": "500 词",
      "bioLong": "Michael Kofman是Digital Invest Inc. CEO并担任董事会成员。他创立了9 Net Avenue Inc.，2000年被Concentric Networks收购，并领导Digital Invest从事生物数学医学和基因组智能。2026年创立AGRON Inc.，从事自主空地作业和地理空间系统。卫星和光学系统技术论文作者；数字卫星HDTV专利被Sony收购。教育：技术科学博士，信息技术博士。",
