    "articles": {
      "backLink": "← العودة إلى Insights",
      "article1date": "منظور تنفيذي",
      "article1title": "من الهندسة إلى البنية التحتية العالمية للبيانات",
      "article1p1": "بدأت مسيرتي في مصنع نيكولايف لبناء السفن في أوكرانيا، حيث طورت أنظمة إرسال واستقبال عبر الأقمار الصناعية لنقل معلومات سرية إلى السفن العسكرية. وتم الاعتراف بي كمهندس إلكترونيات من أعلى مستوى - الفئة السادسة - في مصنع يضم 93,000 موظف.",
      "article1p2": "من 1989 إلى 1994، أسست وقادت Astra Corp، إحدى أكبر الشركات الأوروبية المصنعة لأنظمة الإرسال والاستقبال الفضائية الرقمية. ومن 1994 إلى 1996، وبصفتي CEO لشركة Elitan United Inc.، ساعدت في توسيع الشركة من تسعة موظفين إلى أكثر من 4,000 موظف حول العالم.",
      "article1p3": "في عام 1996، أسست 9 Net Avenue Inc.، شركة استضافة وبنية تحتية للإنترنت. في عام 2000 استحوذت عليها Concentric Networks (NASDAQ: CNTX) وأصبحت لاحقاً جزءاً من XO Communications (NASDAQ: XOXO).",
      "article1p4": "بين 2001 و2019، قدت استراتيجية التكنولوجيا لبرامج حكومية ودفاعية وبرامج الشركات المملوكة للدولة، وقادت مبادرات واسعة في البيانات الضخمة والبنية التحتية الآمنة ومراكز البيانات عالية الإنتاجية عبر الولايات المتحدة وأوروبا.",
      "article2date": "الصحة الرقمية",
      "article2title": "الطب الدقيق وتقاطع العلم مع التكنولوجيا",
      "article2p1": "أنا مؤمن بقوة بإمكانات الجمع بين علوم الحياة وأحدث التطورات التقنية. في Biotechnology Group Inc. (2008-2014)، ركزنا على اختبارات وتحليل الحمض النووي، وأتمتة عمليات إعداد الملفات الجينية، والبحث الجيني البشري الشامل.",
      "article2p2": "تحت قيادتي، انطلقت مشاريع ناجحة للاختبارات الجينية في أوكرانيا وروسيا ودول البلطيق. وبالتعاون مع Harvard Medical School وStanford Biomath، لعبت دورًا محوريًا في تطوير تقارير جينية واضحة وسهلة الفهم للأطباء والمرضى.",
      "article2p3": "مع Digital Invest Inc.، تأسست 2021، نعمل في الطب biomathematical — علم وتقنيات DNA وAI وML في الذكاء clínico. Healthcare Tech Outlook (2023).",
      "article2p4": "تضم Digital Invest مشاريع ابتكارية متعددة، منها Human Digital Model وBioMath Life وAero-Ground Robotics Operations Network، وكل مشروع يدفع تكامل علوم البيانات مع علوم الحياة."
    },
