    "articles": {
      "backLink": "← חזרה ל-Insights",
      "article1date": "פרספקטיבה מנהלית",
      "article1title": "מהנדסה לתשתיות נתונים גלובליות",
      "article1p1": "הקריירה שלי החלה במפעל לבניית ספינות בניקולאייב שבאוקראינה, בפיתוח מערכות משדר-מקלט לווייניות להעברת מידע מסווג לספינות צבאיות. הוכרתי כמהנדס אלקטרוניקה ברמה הגבוהה ביותר - קטגוריה 6 - במפעל של 93,000 עובדים.",
      "article1p2": "בין 1989 ל-1994 ייסדתי והובלתי את Astra Corp, אחת היצרניות הגדולות באירופה של מערכות לוויין דיגיטליות מסוג משדר-מקלט. בין 1994 ל-1996, כ-CEO של Elitan United Inc., סייעתי להרחבת החברה מתשעה עובדים ליותר מ-4,000 עובדים ברחבי העולם.",
      "article1p3": "ב-1996 ייסדתי את 9 Net Avenue Inc., חברת אירוח ותשתית אינטרנט. ב-2000 נרכשה על ידי Concentric Networks (NASDAQ: CNTX) והפכה לאחר מכן לחלק מ-XO Communications (NASDAQ: XOXO).",
      "article1p4": "בין 2001 ל-2019 הובלתי אסטרטגיית טכנולוגיה לתוכניות ממשלתיות, ביטחוניות ולחברות בבעלות מדינה, תוך הובלת יוזמות רחבות היקף בתחומי Big Data, תשתיות מאובטחות ומרכזי נתונים בתפוקה גבוהה בארצות הברית ובאירופה.",
      "article2date": "בריאות דיגיטלית",
      "article2title": "רפואה מדויקת והמפגש בין מדע לטכנולוגיה",
      "article2p1": "אני מאמין עמוקות בפוטנציאל של שילוב מדעי החיים עם החידושים הטכנולוגיים המתקדמים ביותר. ב-Biotechnology Group Inc. ‏(2008-2014) התמקדנו בבדיקות וניתוחי DNA, אוטומציה של תהליכי יצירת פרופילים גנטיים, ומחקר גנטי מקיף של האדם.",
      "article2p2": "תחת הנהגתי, הושקו פרויקטים מוצלחים של בדיקות גנטיות באוקראינה, רוסיה ומדינות הבלטיות. בשיתוף עם Harvard Medical School ו-Stanford Biomath מילאתי תפקיד מרכזי בפיתוח דוחות גנטיים מובנים לרופאים ולמטופלים.",
      "article2p3": "עם Digital Invest Inc., שהוקמה ב-2021, עובדים ברפואה ביו-מתמטית — מדע, טכנולוגיות DNA, AI ו-ML באינטליגנציה clínico. Healthcare Tech Outlook (2023).",
      "article2p4": "Digital Invest כוללת פרויקטים חדשניים מגוונים, בהם Human Digital Model, ‏BioMath Life ו-Aero-Ground Robotics Operations Network - וכל אחד מהם מקדם את שילוב מדעי הנתונים עם מדעי החיים."
    },
